INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, status, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES
('feb9d4e7-6ba8-48a9-b1e1-9a5c11b6260b', 'e46eb157-75b5-49e0-8951-c63ea944fde6', 'HEADING', 1, jsonb_build_object('text', 'Masalah: Ingin Berkebun tapi Tak Punya Lahan')),
('a45a71d4-f60c-43b8-9981-76be6cb58907', 'e46eb157-75b5-49e0-8951-c63ea944fde6', 'PARAGRAPH', 2, jsonb_build_object('text', 'Banyak orang ingin berkebun untuk sayuran segar atau sekadar hobi, tetapi terkendala tidak memiliki halaman. Padahal balkon, teras, atau sudut rumah seluas 1 meter persegi sudah cukup untuk memulai kebun mini yang produktif.')),
('27e3cf1d-e4bc-4d76-9ff9-19868bced6b8', 'e46eb157-75b5-49e0-8951-c63ea944fde6', 'HEADING', 3, jsonb_build_object('text', 'Penjelasan: Konsep Urban Farming dalam Pot')),
('6f77cfdc-b8c9-4cd0-bfa8-defb7c369417', 'e46eb157-75b5-49e0-8951-c63ea944fde6', 'PARAGRAPH', 4, jsonb_build_object('text', 'Berkebun dalam pot (container gardening) adalah teknik menanam memakai wadah berukuran terbatas. Kunci keberhasilannya ada tiga: wadah yang memadai, media tanam yang gembur dan subur, serta tanaman yang sesuai dengan ukuran wadah dan cahaya yang tersedia.')),
('cfe721d9-1016-4705-9814-757c2f4ae42a', 'e46eb157-75b5-49e0-8951-c63ea944fde6', 'HEADING', 5, jsonb_build_object('text', 'Alat dan Bahan yang Dibutuhkan')),
('a0f02dd7-b5b8-4e9a-acb8-d7b5d46ddccd', 'e46eb157-75b5-49e0-8951-c63ea944fde6', 'LIST', 6, jsonb_build_object('items', ARRAY['Pot atau polybag ukuran 25-40 cm (pilih yang berlubang di bawah)', 'Media tanam: campuran tanah, sekam bakar, dan kompos dengan perbandingan 2:1:1', 'Benih atau bibit: kangkung, bayam, cabai, atau tomat ceri', 'Sekop kecil, gembor atau semprotan air', 'Pupuk organik cair (POC) untuk pemupukan berkala'])),
('abc3c256-be21-4645-8044-b905929fd690', 'e46eb157-75b5-49e0-8951-c63ea944fde6', 'HEADING', 7, jsonb_build_object('text', 'Langkah Memulai')),
('57b439b2-f06e-46b9-ba17-5fbabfebecd0', 'e46eb157-75b5-49e0-8951-c63ea944fde6', 'LIST', 8, jsonb_build_object('items', ARRAY['1. Siapkan pot, pastikan ada lubang drainase agar akar tidak busuk', '2. Isi media tanam hingga 3/4 tinggi pot, lalu siram hingga lembap', '3. Tanam benih sedalam 1-2 cm atau pindahkan bibit dengan hati-hati', '4. Letakkan pot di tempat yang mendapat sinar matahari 4-6 jam sehari', '5. Siram setiap pagi (dan sore saat musim kemarau) secukupnya', '6. Beri pupuk organik cair seminggu sekali setelah tanaman berumur 2 minggu'])),
('05ebce95-fe08-4477-b404-63b2c89799e4', 'e46eb157-75b5-49e0-8951-c63ea944fde6', 'HEADING', 9, jsonb_build_object('text', 'Risiko dan Tantangan')),
('6f859204-29c0-491d-8a2c-c4e809ef8d6f', 'e46eb157-75b5-49e0-8951-c63ea944fde6', 'PARAGRAPH', 10, jsonb_build_object('text', 'Hama seperti kutu daun dan ulat bisa menyerang; atasi dengan semprotan air sabun atau pestisida nabati dari bawang putih. Risiko terbesar adalah penyiraman berlebihan yang membuat akar busuk — selalu cek kelembapan media dengan jari sebelum menyiram.')),
('04a105dd-bed0-4e43-878d-20053d97bfb3', 'e46eb157-75b5-49e0-8951-c63ea944fde6', 'HEADING', 11, jsonb_build_object('text', 'Penyelesaian dan Tips Lanjutan')),
('c5fc801c-3120-42c2-bff8-936f211ea235', 'e46eb157-75b5-49e0-8951-c63ea944fde6', 'PARAGRAPH', 12, jsonb_build_object('text', 'Kangkung dan bayam bisa dipanen dalam 25-30 hari, cabai mulai berbuah setelah 2-3 bulan. Setelah panen pertama, tanam ulang (replanting) agar kebun pot terus produktif. Catat jadwal tanam dan panen di buku kecil agar siklus kebunmu makin teratur.'));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, status, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES
('8cb3617c-8f98-440f-a647-e84000a5c940', 'eb5cbfca-5637-4590-b9ea-c4c24f4beeb6', 'HEADING', 1, jsonb_build_object('text', 'Masalah: Ayah Baru yang Bingung Merawat Bayi')),
('9434e5d1-631b-4715-b174-31ece40a8c55', 'eb5cbfca-5637-4590-b9ea-c4c24f4beeb6', 'PARAGRAPH', 2, jsonb_build_object('text', 'Banyak ayah merasa canggung memegang bayi yang mungil dan takut salah. Padahal keterlibatan ayah sejak dini penting untuk ikatan batin (bonding) dan meringankan beban ibu, terutama di 6 bulan pertama yang paling melelahkan.')),
('5c1f0a1f-8281-48f5-a694-850cec52be73', 'eb5cbfca-5637-4590-b9ea-c4c24f4beeb6', 'HEADING', 3, jsonb_build_object('text', 'Penjelasan: Kebutuhan Dasar Bayi 0-6 Bulan')),
('e25bfae2-f5a6-44c5-bd71-395d78f2d462', 'eb5cbfca-5637-4590-b9ea-c4c24f4beeb6', 'PARAGRAPH', 4, jsonb_build_object('text', 'Bayi 0-6 bulan hanya punya kebutuhan dasar: ASI/susu setiap 2-3 jam, popok kering, tidur 14-17 jam sehari, dan rasa aman dari pelukan. Tugas ayah adalah menguasai keempat hal ini — tidak perlu keahlian khusus, hanya keberanian mencoba dan konsistensi.')),
('7edc046a-11af-4696-8558-995b4132d6df', 'eb5cbfca-5637-4590-b9ea-c4c24f4beeb6', 'HEADING', 5, jsonb_build_object('text', 'Persiapan Alat dan Perlengkapan')),
('f068ceea-bbcd-4954-b81d-6526055fd844', 'eb5cbfca-5637-4590-b9ea-c4c24f4beeb6', 'LIST', 6, jsonb_build_object('items', ARRAY['Popok sekali pakai atau kain, tisu basah bayi, dan krim ruam popok', 'Bak mandi bayi, waslap lembut, sabun dan sampo khusus bayi', 'Pakaian ganti bayi, bedong/kain muslin, dan selimut tipis', 'Termometer digital dan obat penurun panas bayi (sesuai anjuran dokter)', 'Gendongan ergonomis agar ayah bisa menggendong dengan aman'])),
('d4636130-b019-4857-92d9-6d2170988596', 'eb5cbfca-5637-4590-b9ea-c4c24f4beeb6', 'HEADING', 7, jsonb_build_object('text', 'Langkah Merawat Bayi Sehari-hari')),
('afd3aeec-5834-4d14-b6bb-5f6144f2332e', 'eb5cbfca-5637-4590-b9ea-c4c24f4beeb6', 'LIST', 8, jsonb_build_object('items', ARRAY['1. Mengganti popok: buka popok kotor, bersihkan dari depan ke belakang, keringkan, oles krim, pasang popok baru', '2. Memandikan: gunakan air hangat suam kuku, pegang kepala dan leher dengan mantap, mandikan 5-10 menit', '3. Menenangkan tangisan: cek popok-lapar-ngantuk dulu, lalu gendong dengan posisi tegak dan goyangkan perlahan', '4. Menyendawakan: setelah menyusu, tegakkan bayi di bahu dan tepuk punggung pelan hingga bersendawa', '5. Menidurkan: buat rutinitas — mandi, bedong, redupkan lampu, nyanyikan lagu yang sama'])),
('c13076db-51e5-444e-885a-a456b048e574', 'eb5cbfca-5637-4590-b9ea-c4c24f4beeb6', 'HEADING', 9, jsonb_build_object('text', 'Risiko dan Tanda Bahaya')),
('c6dbc1ff-e08d-40b9-a3ae-27c9b017ec3f', 'eb5cbfca-5637-4590-b9ea-c4c24f4beeb6', 'PARAGRAPH', 10, jsonb_build_object('text', 'Segera bawa ke dokter jika bayi demam di atas 38 derajat (usia di bawah 3 bulan), menolak menyusu, muntah menyemprot, sesak napas, atau tampak lemas tak responsif. Jangan pernah mengguncang bayi dengan keras (shaken baby syndrome) dan jangan meninggalkan bayi sendirian di tempat tinggi.')),
('ffe1f75c-59d4-40c4-87b7-7feb3dd3f9c4', 'eb5cbfca-5637-4590-b9ea-c4c24f4beeb6', 'HEADING', 11, jsonb_build_object('text', 'Penyelesaian: Menjadi Ayah yang Siap')),
('4767627c-fd06-4b80-b785-1fd4d41c4c64', 'eb5cbfca-5637-4590-b9ea-c4c24f4beeb6', 'PARAGRAPH', 12, jsonb_build_object('text', 'Tidak ada ayah yang langsung mahir — keahlian tumbuh dari latihan harian. Bagi tugas dengan pasangan secara adil, tidur bergantian, dan jangan ragu bertanya ke dokter anak atau orang tua yang berpengalaman. Enam bulan pertama memang berat, tetapi akan jadi memori terindahmu.'));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, status, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES
('82b20a02-dfb1-4fde-937d-76e8d7bdd407', 'eecfdc3c-d2d0-4602-8288-2608436ba73e', 'HEADING', 1, jsonb_build_object('text', 'Pengenalan')),
('ff58341a-1c98-413a-b4d2-0e6110e6a29e', 'eecfdc3c-d2d0-4602-8288-2608436ba73e', 'PARAGRAPH', 2, jsonb_build_object('text', 'Candi Borobudur di Magelang, Jawa Tengah, adalah candi Buddha terbesar di dunia. Dibangun dari sekitar 2 juta balok batu vulkanik, candi ini berbentuk mandala raksasa yang melambangkan perjalanan manusia menuju pencerahan.')),
('572486aa-24e6-42e6-b4af-bcf00a367b3f', 'eecfdc3c-d2d0-4602-8288-2608436ba73e', 'HEADING', 3, jsonb_build_object('text', 'Sejarah Pembangunan')),
('b517b628-a131-4e25-ba09-5888973f33b1', 'eecfdc3c-d2d0-4602-8288-2608436ba73e', 'PARAGRAPH', 4, jsonb_build_object('text', 'Borobudur dibangun pada abad ke-8 hingga ke-9 Masehi pada masa Wangsa Syailendra, kemungkinan atas prakarsa Raja Samaratungga. Setelah berabad-abad tertimbun abu vulkanik dan vegetasi, candi ini ditemukan kembali pada 1814 oleh Thomas Stamford Raffles dan dipugar besar-besaran pada 1975-1982 dengan bantuan UNESCO.')),
('68a114ca-4a77-45a8-872f-7bca79e3efe7', 'eecfdc3c-d2d0-4602-8288-2608436ba73e', 'HEADING', 5, jsonb_build_object('text', 'Arsitektur Mandala')),
('0d0d9ab2-559e-476f-974b-e252ed4d5e7a', 'eecfdc3c-d2d0-4602-8288-2608436ba73e', 'PARAGRAPH', 6, jsonb_build_object('text', 'Candi ini memiliki 10 tingkat: 6 tingkat bujur sangkar, 3 tingkat lingkaran, dan 1 stupa induk di puncak. Denahnya berbentuk mandala — peta kosmos dalam ajaran Buddha. Terdapat 2.672 panel relief dan 504 arca Buddha yang menghiasi dinding dan pagar langkan.')),
('baf2d9ec-3669-451a-9d72-59f7655c9944', 'eecfdc3c-d2d0-4602-8288-2608436ba73e', 'HEADING', 7, jsonb_build_object('text', 'Relief dan Kisah yang Terpahat')),
('c2db37ae-460c-4ba1-a804-220e136bc861', 'eecfdc3c-d2d0-4602-8288-2608436ba73e', 'PARAGRAPH', 8, jsonb_build_object('text', 'Relief Borobudur terbagi dalam beberapa kelompok kisah: Karmawibhangga (hukum karma), Lalitavistara (kisah hidup Buddha), Jataka dan Awadana (kisah kehidupan lampau Buddha), serta Gandawyuha (perjalanan Sudhana mencari kebijaksanaan). Relief ini adalah ensiklopedia visual kehidupan Jawa abad ke-8.')),
('c4611c62-93ac-49c0-87a1-e77cea45501b', 'eecfdc3c-d2d0-4602-8288-2608436ba73e', 'HEADING', 9, jsonb_build_object('text', 'Status Warisan Dunia')),
('0bfb995f-e38d-468b-ab89-1ba2889dff92', 'eecfdc3c-d2d0-4602-8288-2608436ba73e', 'PARAGRAPH', 10, jsonb_build_object('text', 'Sejak 1991, Borobudur tercatat sebagai Situs Warisan Dunia UNESCO. Setiap tahun pada bulan Waisak, ribuan umat Buddha berkumpul di sini untuk merayakan hari raya. Candi ini juga menjadi ikon pariwisata Indonesia yang dikunjungi jutaan wisatawan setiap tahun.'));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, status, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES
('9fd9c63f-94cd-47a8-87dc-1be87b2c5ba6', 'ea7ec9be-44dc-4776-972e-5323018ab422', 'HEADING', 1, jsonb_build_object('text', 'Pengertian ENSO')),
('754e3720-d547-42eb-89c0-d5ec0cddae51', 'ea7ec9be-44dc-4776-972e-5323018ab422', 'PARAGRAPH', 2, jsonb_build_object('text', 'ENSO (El Nino-Southern Oscillation) adalah fenomena interaksi antara suhu permukaan laut dan tekanan udara di Samudra Pasifik tropis. Ia punya dua fase ekstrem: El Nino (fase panas) dan La Nina (fase dingin), yang keduanya memengaruhi cuaca di seluruh dunia, termasuk Indonesia.')),
('3e906c32-b05c-4069-8904-b10a8fb162b2', 'ea7ec9be-44dc-4776-972e-5323018ab422', 'HEADING', 3, jsonb_build_object('text', 'Mekanisme El Nino')),
('5dec3cfa-2919-4922-8fad-232e12c6a0c4', 'ea7ec9be-44dc-4776-972e-5323018ab422', 'PARAGRAPH', 4, jsonb_build_object('text', 'Pada kondisi normal, angin pasat mendorong air hangat ke Pasifik barat (dekat Indonesia) sehingga banyak hujan. Saat El Nino, angin pasat melemah, air hangat bergeser ke Pasifik timur (dekat Peru), dan Indonesia mengalami musim kemarau yang lebih panjang dan kering.')),
('41e37b19-3139-4e56-ab2d-db642f8ab35c', 'ea7ec9be-44dc-4776-972e-5323018ab422', 'HEADING', 5, jsonb_build_object('text', 'Mekanisme La Nina')),
('c341811f-9508-460f-a528-a84b40a97d8f', 'ea7ec9be-44dc-4776-972e-5323018ab422', 'PARAGRAPH', 6, jsonb_build_object('text', 'La Nina adalah kebalikan El Nino: angin pasat menguat, air hangat menumpuk lebih banyak di Pasifik barat. Akibatnya Indonesia menerima curah hujan di atas normal — musim hujan lebih lebat, lebih lama, dan rawan banjir serta longsor.')),
('87b6b3d2-0bea-435a-a487-5274fa79ac4e', 'ea7ec9be-44dc-4776-972e-5323018ab422', 'HEADING', 7, jsonb_build_object('text', 'Dampak ke Indonesia')),
('f143ad68-b809-46e7-886f-d2d13fe6b2c9', 'ea7ec9be-44dc-4776-972e-5323018ab422', 'PARAGRAPH', 8, jsonb_build_object('text', 'El Nino kuat (seperti 1997-1998 dan 2015) menyebabkan kekeringan parah: gagal panen, krisis air bersih, dan kebakaran hutan dan lahan. La Nina kuat (seperti 2010-2011) menyebabkan banjir bandang di banyak daerah dan gagal panen karena tanaman terendam.')),
('63b0a890-2785-476e-9ad8-c27f0637f289', 'ea7ec9be-44dc-4776-972e-5323018ab422', 'HEADING', 9, jsonb_build_object('text', 'Cara Mengantisipasi')),
('15e5325e-c234-48c0-b6f9-eeeca41b481d', 'ea7ec9be-44dc-4776-972e-5323018ab422', 'PARAGRAPH', 10, jsonb_build_object('text', 'BMKG memantau suhu muka laut dan merilis peringatan dini beberapa bulan sebelumnya. Petani bisa menyesuaikan kalender tanam, pemerintah daerah menyiapkan lumbung pangan dan pompa air saat El Nino, serta normalisasi drainase dan siaga banjir saat La Nina.'));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, status, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES
('4f1b0cfb-d797-4bad-bde1-c5b974f58009', 'ec52bdd4-0aae-4153-903d-4bd499cad6dc', 'HEADING', 1, jsonb_build_object('text', 'Tujuan Pembelajaran')),
('29337024-2aa4-4f74-83fa-1f66c1ef7e8a', 'ec52bdd4-0aae-4153-903d-4bd499cad6dc', 'PARAGRAPH', 2, jsonb_build_object('text', 'Setelah mempelajari materi ini, kamu diharapkan mampu menjelaskan konsep garis Wallace dan Weber, mengidentifikasi tiga zona persebaran flora dan fauna di Indonesia, serta memberi contoh tumbuhan dan hewan khas tiap zona.')),
('284610b5-70da-464b-bdbe-8c2b8eb24583', 'ec52bdd4-0aae-4153-903d-4bd499cad6dc', 'HEADING', 3, jsonb_build_object('text', 'Garis Wallace dan Weber')),
('cb6eea29-c9d4-4158-92e2-dd57701fecce', 'ec52bdd4-0aae-4153-903d-4bd499cad6dc', 'PARAGRAPH', 4, jsonb_build_object('text', 'Alfred Russel Wallace (1859) mengamati bahwa fauna Indonesia bagian barat mirip Asia, sedangkan bagian timur mirip Australia. Ia menarik garis khayal (Garis Wallace) di antara Kalimantan-Sulawesi dan Bali-Lombok. Max Wilhelm Weber kemudian menarik garis kedua (Garis Weber) di sebelah timur sebagai batas fauna peralihan.')),
('34c03bce-f0a2-4601-96e1-a649ad2cfad8', 'ec52bdd4-0aae-4153-903d-4bd499cad6dc', 'HEADING', 5, jsonb_build_object('text', 'Tiga Zona Persebaran')),
('a8477213-7274-4a9a-b189-f6d924b77567', 'ec52bdd4-0aae-4153-903d-4bd499cad6dc', 'LIST', 6, jsonb_build_object('items', ARRAY['Zona Asiatis (barat): Sumatra, Jawa, Kalimantan, Bali — flora fauna mirip Asia', 'Zona Peralihan (tengah): Sulawesi, Nusa Tenggara, Maluku — campuran khas', 'Zona Australis (timur): Papua — flora fauna mirip Australia'])),
('d6e32343-e97b-4afb-b65e-71b4c54f9816', 'ec52bdd4-0aae-4153-903d-4bd499cad6dc', 'HEADING', 7, jsonb_build_object('text', 'Contoh Flora per Zona')),
('ec6c8943-52bc-44cb-87e6-cef6954c1167', 'ec52bdd4-0aae-4153-903d-4bd499cad6dc', 'PARAGRAPH', 8, jsonb_build_object('text', 'Zona Asiatis: meranti, jati, rafflesia arnoldii. Zona Peralihan: kayu eboni (Sulawesi), lontar (Nusa Tenggara). Zona Australis: sagu, kayu putih, anggrek khas Papua.')),
('cba197ba-a6ec-4153-a5c4-6ed70f6d932d', 'ec52bdd4-0aae-4153-903d-4bd499cad6dc', 'HEADING', 9, jsonb_build_object('text', 'Contoh Fauna per Zona')),
('bd3ad8e3-a357-4220-9c31-f19071d21944', 'ec52bdd4-0aae-4153-903d-4bd499cad6dc', 'PARAGRAPH', 10, jsonb_build_object('text', 'Zona Asiatis: orangutan, harimau sumatra, gajah sumatra, bekantan. Zona Peralihan: anoa, komodo, babirusa, maleo. Zona Australis: kasuari, cenderawasih, kangguru pohon, kuskus.')),
('88c6d0f3-2cbd-4289-91da-271fbbdb1fbb', 'ec52bdd4-0aae-4153-903d-4bd499cad6dc', 'HEADING', 11, jsonb_build_object('text', 'Latihan Soal')),
('a646e91f-2b2e-48c8-ae67-d382890a0e5a', 'ec52bdd4-0aae-4153-903d-4bd499cad6dc', 'LIST', 12, jsonb_build_object('items', ARRAY['1. Jelaskan perbedaan Garis Wallace dan Garis Weber!', '2. Sebutkan 3 hewan khas zona peralihan beserta daerahnya!', '3. Mengapa komodo hanya ditemukan di Nusa Tenggara?'])),
('3ad86902-f264-493c-b56a-2718f38aa07f', 'ec52bdd4-0aae-4153-903d-4bd499cad6dc', 'HEADING', 13, jsonb_build_object('text', 'Kunci Jawaban')),
('a688b418-5ed5-44bd-82bd-ce3cd35e2ea5', 'ec52bdd4-0aae-4153-903d-4bd499cad6dc', 'PARAGRAPH', 14, jsonb_build_object('text', '1. Garis Wallace memisahkan fauna Asiatis dan peralihan (barat-tengah); Garis Weber memisahkan fauna peralihan dan Australis (tengah-timur). 2. Komodo (Flores), anoa (Sulawesi), maleo (Sulawesi). 3. Karena zona peralihan bersifat terisolasi dan komodo berevolusi khusus di pulau-pulau kecil Nusa Tenggara tanpa predator besar pesaing.'));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, status, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES
('78ab2196-4d65-4bb9-af78-c978e547d1f2', 'e342220a-da81-413e-9b7c-c402294edebe', 'HEADING', 1, jsonb_build_object('text', 'Tujuan Pembelajaran')),
('3b50caea-0f2b-497a-801c-4c84c721d0ed', 'e342220a-da81-413e-9b7c-c402294edebe', 'PARAGRAPH', 2, jsonb_build_object('text', 'Setelah belajar materi ini, kamu bisa menyebutkan ciri-ciri bangun datar (persegi, persegi panjang, segitiga, lingkaran), menghitung luas dan kelilingnya, serta menyelesaikan soal cerita yang berkaitan.')),
('5436f7a6-8065-4153-9c30-44ee388eef52', 'e342220a-da81-413e-9b7c-c402294edebe', 'HEADING', 3, jsonb_build_object('text', 'Persegi dan Persegi Panjang')),
('a65bc9ca-2e83-494d-a035-1ffcb7b4eeae', 'e342220a-da81-413e-9b7c-c402294edebe', 'PARAGRAPH', 4, jsonb_build_object('text', 'Persegi punya 4 sisi sama panjang. Luas = sisi x sisi, keliling = 4 x sisi. Persegi panjang punya 2 pasang sisi sejajar sama panjang. Luas = panjang x lebar, keliling = 2 x (panjang + lebar).')),
('c8900a4c-74df-473b-a0c3-57cf6cf987d0', 'e342220a-da81-413e-9b7c-c402294edebe', 'HEADING', 5, jsonb_build_object('text', 'Segitiga')),
('2e0ad32a-8fdb-44e2-a26b-3ac58715f532', 'e342220a-da81-413e-9b7c-c402294edebe', 'PARAGRAPH', 6, jsonb_build_object('text', 'Segitiga punya 3 sisi dan 3 sudut. Luas = 1/2 x alas x tinggi, keliling = jumlah ketiga sisinya. Tinggi segitiga adalah garis tegak lurus dari alas ke titik sudut di atasnya.')),
('c01b4465-ec44-4791-949c-6fbfa8c1bab2', 'e342220a-da81-413e-9b7c-c402294edebe', 'HEADING', 7, jsonb_build_object('text', 'Lingkaran')),
('47824137-eb5f-4ee4-b5a7-9c85cbcea10c', 'e342220a-da81-413e-9b7c-c402294edebe', 'PARAGRAPH', 8, jsonb_build_object('text', 'Lingkaran tidak punya sisi, melainkan jari-jari (r) dan diameter (d = 2 x r). Luas = phi x r x r, keliling = 2 x phi x r. Nilai phi bisa 22/7 (jika r kelipatan 7) atau 3,14.')),
('d5d42080-0068-4cd5-81d7-79bdc799037c', 'e342220a-da81-413e-9b7c-c402294edebe', 'HEADING', 9, jsonb_build_object('text', 'Contoh Soal Langkah demi Langkah')),
('8ae77c6d-5fab-40a8-b980-7b2226b36986', 'e342220a-da81-413e-9b7c-c402294edebe', 'PARAGRAPH', 10, jsonb_build_object('text', 'Contoh 1: Kebun persegi panjang panjang 12 m lebar 8 m. Luas = 12 x 8 = 96 m persegi. Keliling = 2 x (12 + 8) = 40 m. Contoh 2: Lingkaran berjari-jari 7 cm. Luas = 22/7 x 7 x 7 = 154 cm persegi. Keliling = 2 x 22/7 x 7 = 44 cm.')),
('597c4af1-83f9-4c45-9fd4-118e61b24379', 'e342220a-da81-413e-9b7c-c402294edebe', 'HEADING', 11, jsonb_build_object('text', 'Latihan Soal')),
('8ff33bbf-ca87-404c-9eac-e5a3fb5b4438', 'e342220a-da81-413e-9b7c-c402294edebe', 'LIST', 12, jsonb_build_object('items', ARRAY['1. Sebuah persegi memiliki sisi 9 cm. Hitung luas dan kelilingnya!', '2. Segitiga dengan alas 10 cm dan tinggi 6 cm. Berapa luasnya?', '3. Taman berbentuk lingkaran berdiameter 14 m. Hitung kelilingnya!'])),
('35bb9324-a334-44ff-a36e-669857359042', 'e342220a-da81-413e-9b7c-c402294edebe', 'HEADING', 13, jsonb_build_object('text', 'Kunci Jawaban')),
('f2fdb50f-a8be-401d-92b3-90d7760a3beb', 'e342220a-da81-413e-9b7c-c402294edebe', 'PARAGRAPH', 14, jsonb_build_object('text', '1. Luas = 9 x 9 = 81 cm persegi; keliling = 4 x 9 = 36 cm. 2. Luas = 1/2 x 10 x 6 = 30 cm persegi. 3. Jari-jari = 14/2 = 7 m; keliling = 2 x 22/7 x 7 = 44 m.'));
